using System.Collections.Generic;
using UnityEngine;

/// <summary>
/// A* 寻路算法 — Octile Distance 启发式，8 方向移动，拐角检查。
/// </summary>
public static class AStarPathfinder
{
    private const float D = 1f;        // 直线移动代价
    private const float D2 = 1.4142f;  // 对角线移动代价 (√2)

    /// <summary>
    /// 返回从 start 到 end 的路径点列表（世界坐标），不含起点，含终点。
    /// 无路径返回 null。
    /// </summary>
    public static List<Vector2> FindPath(Vector2 start, Vector2 end,
        PathfindingGrid grid, int maxNodes = 500)
    {
        var startCell = grid.WorldToCell(start);
        var endCell = grid.WorldToCell(end);

        if (!grid.InBounds(startCell.x, startCell.y))
            startCell = grid.ClampToGrid(start);
        if (!grid.InBounds(endCell.x, endCell.y))
            endCell = grid.ClampToGrid(end);

        if (!grid.IsWalkable(endCell.x, endCell.y))
        {
            endCell = grid.FindNearestWalkable(endCell);
            if (endCell.x < 0) return null;
        }

        var openSet = new List<AStarNode>();
        var closedSet = new HashSet<Vector2Int>();
        var cameFrom = new Dictionary<Vector2Int, Vector2Int>();
        var gScore = new Dictionary<Vector2Int, float>();
        var fScore = new Dictionary<Vector2Int, float>();

        var startKey = new Vector2Int(startCell.x, startCell.y);
        var endKey = new Vector2Int(endCell.x, endCell.y);

        gScore[startKey] = 0;
        fScore[startKey] = Heuristic(startCell, endCell);
        openSet.Add(new AStarNode(startKey, fScore[startKey]));

        int nodesExplored = 0;

        while (openSet.Count > 0 && nodesExplored < maxNodes)
        {
            // 取 fScore 最小的节点
            openSet.Sort((a, b) => a.F.CompareTo(b.F));
            var current = openSet[0];
            openSet.RemoveAt(0);

            if (current.Cell == endKey)
                return ReconstructPath(cameFrom, current.Cell, grid);

            closedSet.Add(current.Cell);
            nodesExplored++;

            // 8 方向邻居
            for (int dx = -1; dx <= 1; dx++)
            {
                for (int dy = -1; dy <= 1; dy++)
                {
                    if (dx == 0 && dy == 0) continue;

                    int nx = current.Cell.x + dx;
                    int ny = current.Cell.y + dy;
                    var neighbor = new Vector2Int(nx, ny);

                    if (!grid.InBounds(nx, ny)) continue;
                    if (!grid.IsWalkable(nx, ny)) continue;
                    if (closedSet.Contains(neighbor)) continue;

                    // 对角线拐角检查：两个正交邻居必须均可通行
                    if (dx != 0 && dy != 0)
                    {
                        if (!grid.IsWalkable(current.Cell.x + dx, current.Cell.y)) continue;
                        if (!grid.IsWalkable(current.Cell.x, current.Cell.y + dy)) continue;
                    }

                    float moveCost = (dx != 0 && dy != 0) ? D2 : D;
                    float tentativeG = gScore[current.Cell] + moveCost;

                    if (!gScore.ContainsKey(neighbor) || tentativeG < gScore[neighbor])
                    {
                        cameFrom[neighbor] = current.Cell;
                        gScore[neighbor] = tentativeG;
                        fScore[neighbor] = tentativeG + Heuristic(neighbor, endKey);

                        if (!openSet.Exists(n => n.Cell == neighbor))
                            openSet.Add(new AStarNode(neighbor, fScore[neighbor]));
                    }
                }
            }
        }

        return null; // 无路径
    }

    /// <summary>Octile Distance — 匹配 8 方向移动</summary>
    private static float Heuristic(Vector2Int a, Vector2Int b)
    {
        int dx = Mathf.Abs(a.x - b.x);
        int dy = Mathf.Abs(a.y - b.y);
        return D * (dx + dy) + (D2 - 2f * D) * Mathf.Min(dx, dy);
    }

    /// <summary>重建路径 → 世界坐标列表</summary>
    private static List<Vector2> ReconstructPath(
        Dictionary<Vector2Int, Vector2Int> cameFrom,
        Vector2Int current, PathfindingGrid grid)
    {
        var path = new List<Vector2>();
        var cell = current;
        while (cameFrom.ContainsKey(cell))
        {
            path.Add(grid.CellToWorld(cell.x, cell.y));
            cell = cameFrom[cell];
        }
        path.Reverse();
        return path;
    }

    private struct AStarNode
    {
        public Vector2Int Cell;
        public float F;
        public AStarNode(Vector2Int cell, float f) { Cell = cell; F = f; }
    }
}

using System.Collections.Generic;
using UnityEngine;

/// <summary>
/// 寻路网格 — 运行时构建，存储在 RoomRoot 中供敌人共享。
/// 使用虚拟矩形栅格化检测障碍物（Rect.Overlaps vs Collider.bounds）。
/// </summary>
public class PathfindingGrid
{
    private readonly bool[,] _walkable;
    private readonly Vector2 _origin;
    private readonly float _cellSize;
    private readonly int _width;
    private readonly int _height;

    public int Width => _width;
    public int Height => _height;
    public Vector2 Origin => _origin;
    public float CellSize => _cellSize;

    public PathfindingGrid(Vector2 origin, int width, int height, float cellSize)
    {
        _origin = origin;
        _width = width;
        _height = height;
        _cellSize = cellSize;
        _walkable = new bool[width, height];
    }

    /// <summary>
    /// 虚拟矩形栅格化构建：
    /// 1. 收集房间范围内所有 Wall/Obstacles 的 Collider.bounds
    /// 2. 每个 cell 的 Rect（收缩 shrink）与障碍物 bounds 做交集检测
    /// </summary>
    public static PathfindingGrid Build(Vector2 center, Vector2 roomSize, float cellSize = 1f)
    {
        int width = Mathf.RoundToInt(roomSize.x / cellSize);
        int height = Mathf.RoundToInt(roomSize.y / cellSize);
        Vector2 origin = center - new Vector2(width * cellSize * 0.5f, height * cellSize * 0.5f);

        var grid = new PathfindingGrid(origin, width, height, cellSize);

        // 每个 cell 中心用 OverlapCircle 检测是否有障碍碰撞体
        float checkRadius = cellSize * 0.25f;

        for (int x = 0; x < width; x++)
        {
            for (int y = 0; y < height; y++)
            {
                Vector2 cellCenter = grid.CellToWorld(x, y);
                var hits = Physics2D.OverlapCircleAll(cellCenter, checkRadius);
                bool blocked = false;
                foreach (var hit in hits)
                {
                    if (hit.CompareTag("Wall") || hit.CompareTag("Obstacles") || hit.CompareTag("Spike") || hit.CompareTag("Hole"))
                    {
                        blocked = true;
                        break;
                    }
                }
                grid._walkable[x, y] = !blocked;
            }
        }
        return grid;
    }

    public bool IsWalkable(int x, int y)
    {
        if (!InBounds(x, y)) return false;
        return _walkable[x, y];
    }

    public bool InBounds(int x, int y) => x >= 0 && x < _width && y >= 0 && y < _height;

    public Vector2Int WorldToCell(Vector2 worldPos)
    {
        Vector2 local = worldPos - _origin;
        return new Vector2Int(
            Mathf.FloorToInt(local.x / _cellSize),
            Mathf.FloorToInt(local.y / _cellSize));
    }

    public Vector2 CellToWorld(int x, int y)
    {
        return _origin + new Vector2(
            (x + 0.5f) * _cellSize,
            (y + 0.5f) * _cellSize);
    }

    public Vector2Int ClampToGrid(Vector2 worldPos)
    {
        var cell = WorldToCell(worldPos);
        cell.x = Mathf.Clamp(cell.x, 0, _width - 1);
        cell.y = Mathf.Clamp(cell.y, 0, _height - 1);
        return cell;
    }

    /// <summary>找最近的可通行 cell（螺旋搜索）</summary>
    public Vector2Int FindNearestWalkable(Vector2Int center)
    {
        if (IsWalkable(center.x, center.y)) return center;
        for (int r = 1; r < 10; r++)
        {
            for (int dx = -r; dx <= r; dx++)
            {
                for (int dy = -r; dy <= r; dy++)
                {
                    if (Mathf.Max(Mathf.Abs(dx), Mathf.Abs(dy)) != r) continue;
                    int x = center.x + dx;
                    int y = center.y + dy;
                    if (InBounds(x, y) && IsWalkable(x, y))
                        return new Vector2Int(x, y);
                }
            }
        }
        return new Vector2Int(-1, -1);
    }
}

using System.Collections.Generic;
using UnityEngine;

/// <summary>
/// 移动组件：封装 Rigidbody2D 操作与视线检测缓存。
///
/// 速度数据源：EnemyStats.PatrolSpeed / EnemyStats.ChaseSpeed
///             由状态机在调用 MoveTowardsPosition 时显式传入。
/// </summary>
[RequireComponent(typeof(Rigidbody2D))]
public class EnemyMovement : MonoBehaviour
{
    [Tooltip("全局敌人速度倍率（道具效果），1=正常，0.5=半速")]
    public static float GlobalSpeedMultiplier = 1f;

    private Rigidbody2D _rb;
    private float _nextSightCheckTime;
    private bool _cachedHasLineOfSight;
    private bool _wasInDetectionRange = false;

    // === 寻路状态 ===
    private PathfindingGrid _grid;
    private List<Vector2> _cachedPath;
    private int _pathIndex;
    private Vector2 _lastPathTarget;
    private float _nextPathRecomputeTime;
    private bool _isFollowingComplexPath;

    private const float PathRecomputeInterval = 0.3f;
    private const float TargetMoveThreshold = 1f;
    private const float ArriveThreshold = 0.2f;

    private void Awake()
    {
        _rb = GetComponent<Rigidbody2D>();
        if (_rb != null) _rb.freezeRotation = true;
    }

    public void Stop()
    {
        if (_rb != null) _rb.velocity = Vector2.zero;
    }

    /// <summary>
    /// 向目标位置移动。
    /// </summary>
    /// <param name="target">目标世界坐标</param>
    /// <param name="speed">移动速度</param>
    /// <param name="speedMultiplier">额外速度倍率（0~1），用于搜索等减速行为</param>
    public void MoveTowardsPosition(Vector2 target, float speed, float speedMultiplier = 1f)
    {
        if (_rb == null || speed <= 0f) return;
        Vector2 dir = (target - (Vector2)transform.position).normalized;
        _rb.velocity = dir * speed * speedMultiplier * GlobalSpeedMultiplier;
    }

    public void SetVelocity(Vector2 vel)
    {
        if (_rb == null) return;
        _rb.velocity = vel * GlobalSpeedMultiplier;
    }

    /// <summary>直接传送到目标位置</summary>
    public void Teleport(Vector2 targetPos)
    {
        if (_rb != null)
        {
            _rb.velocity = Vector2.zero;
            _rb.position = targetPos;
        }
        else
        {
            transform.position = targetPos;
        }
    }

    /// <summary>
    /// 带缓存的视线检测。
    /// </summary>
    public bool HasLineOfSight(Vector2 targetPosition, float detectionRange, float sightCheckInterval = 0.2f)
    {
        float sqrDistance = ((Vector2)transform.position - targetPosition).sqrMagnitude;
        bool inRange = sqrDistance <= detectionRange * detectionRange;

        if (!inRange)
        {
            _wasInDetectionRange = false;
            _cachedHasLineOfSight = false;
            return false;
        }

        if (!_wasInDetectionRange)
        {
            _nextSightCheckTime = 0f;
            _wasInDetectionRange = true;
        }

        if (Time.time >= _nextSightCheckTime)
        {
            _nextSightCheckTime = Time.time + sightCheckInterval;
            RaycastHit2D hit = Physics2D.Linecast(transform.position, targetPosition);
            _cachedHasLineOfSight = hit.collider == null || !hit.collider.CompareTag("Wall");
        }

        return _cachedHasLineOfSight;
    }

    // ==================== 寻路 API ====================

    public void SetRoomGrid(PathfindingGrid grid) { _grid = grid; }

    /// <summary>
    /// 矩形检测：以敌人为中心，沿 dir 方向检测 checkDist 距离内是否有障碍或墙。
    /// 矩形宽=敌人直径，长=checkDist。
    /// </summary>
    public bool IsDirectionBlocked(Vector2 dir, float checkDist = 0.5f)
    {
        Vector2 start = transform.position;
        Vector2 normalizedDir = dir.normalized;
        if (normalizedDir == Vector2.zero) return false;

        float enemyDiameter = GetEnemyDiameter();
        Vector2 target = start + normalizedDir * checkDist;
        Vector2 center = (start + target) / 2f;
        float angle = Mathf.Atan2(normalizedDir.y, normalizedDir.x) * Mathf.Rad2Deg;
        Vector2 size = new Vector2(checkDist, enemyDiameter);

        var hits = Physics2D.OverlapBoxAll(center, size, angle);
        foreach (var hit in hits)
        {
            if (hit.CompareTag("Wall") || hit.CompareTag("Obstacles") || hit.CompareTag("Spike") || hit.CompareTag("Hole"))
                return true;
        }
        return false;
    }

    /// <summary>
    /// 矩形视线检测 — 矩形宽=敌人直径，方向朝目标。
    /// 用于寻路判断（与发现玩家的 HasLineOfSight 不同）。
    /// </summary>
    public bool HasObstacleInPath(Vector2 target)
    {
        Vector2 start = transform.position;
        Vector2 dir = target - start;
        float dist = dir.magnitude;
        if (dist < 0.01f) return false;
        dir /= dist;

        float enemyDiameter = GetEnemyDiameter();
        Vector2 center = (start + target) / 2f;
        float angle = Mathf.Atan2(dir.y, dir.x) * Mathf.Rad2Deg;
        Vector2 size = new Vector2(dist, enemyDiameter);

        var hits = Physics2D.OverlapBoxAll(center, size, angle);
        foreach (var hit in hits)
        {
            if (hit.CompareTag("Wall") || hit.CompareTag("Obstacles") || hit.CompareTag("Spike") || hit.CompareTag("Hole"))
                return true;
        }
        return false;
    }

    private float GetEnemyDiameter()
    {
        var sr = GetComponent<SpriteRenderer>();
        if (sr != null && sr.sprite != null)
        {
            float w = sr.sprite.rect.width / sr.sprite.pixelsPerUnit * transform.localScale.x;
            float h = sr.sprite.rect.height / sr.sprite.pixelsPerUnit * transform.localScale.y;
            return Mathf.Max(w, h);
        }
        var col = GetComponent<Collider2D>();
        if (col != null) return Mathf.Max(col.bounds.size.x, col.bounds.size.y);
        return 1f;
    }

    /// <summary>
    /// 获取到目标的路径。无障碍=直线（单点）；有障碍=A*。
    /// _isFollowingComplexPath 锁：路径>1 时强制走完，中途不切直线。
    /// </summary>
    public List<Vector2> GetPath(Vector2 target)
    {
        // 1. 正在跟随复杂路径 → 沿用，除非目标位移过大
        if (_isFollowingComplexPath && _cachedPath != null && _cachedPath.Count > 1)
        {
            if ((target - _lastPathTarget).sqrMagnitude < TargetMoveThreshold * TargetMoveThreshold)
                return _cachedPath;
        }

        // 2. 无有效路径或目标大变 → 重新评估
        bool hasObstacle = HasObstacleInPath(target);

        if (!hasObstacle)
        {
            _cachedPath = new List<Vector2> { target };
            _pathIndex = 0;
            _isFollowingComplexPath = false;
            _lastPathTarget = target;
            return _cachedPath;
        }

        // 3. 有障碍 → A*（冷却检查）
        if (Time.time < _nextPathRecomputeTime && _cachedPath != null && _cachedPath.Count > 1)
            return _cachedPath;

        if (_grid == null)
        {
            _cachedPath = new List<Vector2> { target };
            _pathIndex = 0;
            _isFollowingComplexPath = false;
            _lastPathTarget = target;
            return _cachedPath;
        }

        var path = AStarPathfinder.FindPath(transform.position, target, _grid);
        _nextPathRecomputeTime = Time.time + PathRecomputeInterval;
        _lastPathTarget = target;

        if (path != null && path.Count > 1)
        {
            _cachedPath = path;
            _pathIndex = 0;
            _isFollowingComplexPath = true;
        }
        else
        {
            _cachedPath = new List<Vector2> { target };
            _pathIndex = 0;
            _isFollowingComplexPath = false;
        }
        return _cachedPath;
    }

    /// <summary>
    /// 沿路径点移动。距离阈值 + 投影判断双保险防过冲。
    /// </summary>
    public bool MoveAlongPath(List<Vector2> path, float speed, float speedMultiplier = 1f)
    {
        if (path == null || path.Count == 0) return true;
        if (_rb == null || speed <= 0f) return false;

        Vector2 currentPos = transform.position;
        Vector2 currentTargetPos = path[_pathIndex];
        float sqrDist = (currentPos - currentTargetPos).sqrMagnitude;

        if (sqrDist > ArriveThreshold * ArriveThreshold)
        {
            // 防过冲：如果当前路径点不是最后一个，检查是否已越过该点
            if (_pathIndex < path.Count - 1)
            {
                Vector2 nextTarget = path[_pathIndex + 1];
                Vector2 dirToNext = (nextTarget - currentTargetPos).normalized;
                float projection = Vector2.Dot(currentPos - currentTargetPos, dirToNext);
                if (projection > 0f)
                {
                    _pathIndex++;
                    return false;
                }
            }
            MoveTowardsPosition(currentTargetPos, speed, speedMultiplier);
            return false;
        }

        // 到达当前点 → 推进
        if (_pathIndex < path.Count - 1)
        {
            _pathIndex++;
            return false;
        }

        // 到达终点
        _isFollowingComplexPath = false;
        return true;
    }
}

using UnityEngine;

/// <summary>
/// 随从追击状态：朝最近敌人移动。
/// 敌人消失 → IdleState；进入攻击范围 → AttackState。
/// </summary>
public class FollowerChaseState : FollowerStateBase
{
    public FollowerChaseState(EnemyFollower follower) : base(follower) { }

    public override void Tick()
    {
        Vector2 pos = Core.transform.position;
        Transform enemy = Follower.FindNearestEnemy(pos);

        // 敌人消失 → 待机
        if (enemy == null)
        {
            Follower.StateMachine.ChangeState(new FollowerIdleState(Follower));
            return;
        }

        float dist = Vector2.Distance(pos, enemy.position);

        // 进入攻击范围 → 攻击
        if (dist <= Follower.AttackRange)
        {
            Follower.StateMachine.ChangeState(new FollowerAttackState(Follower));
            return;
        }

        // 追击敌人（A* 寻路）
        var path = Movement.GetPath(enemy.position);
        Movement?.MoveAlongPath(path, Follower.FollowSpeed);
    }
}

using UnityEngine;

/// <summary>
/// 随从跟随状态：朝玩家移动。
/// 发现敌人 → ChaseState；接近玩家 → IdleState。
/// </summary>
public class FollowerFollowState : FollowerStateBase
{
    public FollowerFollowState(EnemyFollower follower) : base(follower) { }

    public override void Tick()
    {
        // 搜索敌人 → 追击
        Vector2 pos = Core.transform.position;
        Transform enemy = Follower.FindNearestEnemy(pos);
        if (enemy != null)
        {
            Follower.StateMachine.ChangeState(new FollowerChaseState(Follower));
            return;
        }

        // 接近玩家 → 待机
        float dist = Vector2.Distance(pos, Player.position);
        if (dist <= Follower.FollowDistance)
        {
            Follower.StateMachine.ChangeState(new FollowerIdleState(Follower));
            return;
        }

        // 朝玩家移动（A* 寻路）
        var path = Movement.GetPath(Player.position);
        Movement?.MoveAlongPath(path, Follower.FollowSpeed);
    }
}

using UnityEngine;
using UnityEngine.SceneManagement;
using System.Collections;

/// <summary>
/// 随从行为组件：接管被同化敌人的 AI。
/// AI 决策由 FollowerStateMachine 驱动（Idle/Follow/Chase/Attack 四状态）。
/// 生命周期管理（传送/复活/跨场景/进化buff/道具增强）保留在本组件中。
/// 由 EnemyCore.Assimilate() 激活。
/// </summary>
[RequireComponent(typeof(EnemyCore))]
public class EnemyFollower : MonoBehaviour
{
    [Header("随从参数")]
    [SerializeField] private float _followDistance = 3.5f;
    [SerializeField] private float _detectionRange = 8f;
    [SerializeField] private float _attackRange = 2f;
    [SerializeField] private float _followSpeed = 3f;
    [Tooltip("离玩家超过此距离时直接传送到身边，防止掉队")]
    [SerializeField] private float _maxTeleportDistance = 15f;

    [Header("同种升级")]
    [Tooltip("同种类随从升级：每级属性倍率增量（0.15 = 每级 +15%）")]
    [SerializeField] private float _levelStatFactor = 0.15f;
    [Tooltip("同种类随从升级：技能等级是否 +1")]
    [SerializeField] private bool _upgradeSkillsOnLevelUp = true;

    [Header("复活")]
    [Tooltip("死亡后复活延迟（秒）")]
    [SerializeField] private float _respawnDelay = 10f;

    private Transform _player;
    private EnemyCore _core;
    private EnemyMovement _movement;
    private EnemySkillManager _skillManager;
    private bool _isActive;
    private bool _isReviving;
    private bool _isPaused;
    private FollowerStateMachine _followerSM;

    // 进化倾向 buff：记录原始属性，动态刷新时从原始值重算
    private float _origMaxHealth, _origPatrolSpeed, _origChaseSpeed;
    private float _origDetectionRange, _origAttackRange, _origContactDamage, _origContactDamageCooldown;

    /// <summary>所有活跃随从列表（供 MapManager 查询，避免 FindObjectsByType）</summary>
    public static readonly System.Collections.Generic.List<EnemyFollower> ActiveFollowers = new();

    /// <summary>随从列表修订号：增删/升级时自增，UI 据此重建行</summary>
    public static int Revision { get; private set; }

    /// <summary>随从槽位索引（0..MaxFollowerCount-1，-1=未分配）</summary>
    public int SlotIndex { get; private set; } = -1;

    /// <summary>随从等级（同种升级叠加，默认 1）</summary>
    public int Level { get; private set; } = 1;

    // ── 道具增强（静态，影响所有随从）──
    /// <summary>随从生命上限乘区（免疫球蛋白）</summary>
    public static float MaxHealthMultiplier = 1f;
    /// <summary>随从伤害乘区（集落刺激因子 CSF）</summary>
    public static float DamageMultiplier = 1f;
    /// <summary>随从技能冷却乘区（白细胞介素-2 IL-2）</summary>
    public static float FollowerCooldownFactor = 1f;
    /// <summary>随从攻击是否附带减速（干扰素）</summary>
    public static bool ApplySlow = false;
    /// <summary>减速比例（干扰素），0.8 = 减速20%</summary>
    public static float SlowFactor = 0.8f;
    /// <summary>减速持续时间（秒）</summary>
    public static float SlowDuration = 2f;
    /// <summary>随从数量上限（胸腺肽），默认4</summary>
    public static int MaxFollowerCount = 4;

    // ── 暴露给状态机的只读属性 ──
    public EnemyCore Core => _core;
    public EnemyMovement Movement => _movement;
    public EnemySkillManager SkillManager => _skillManager;
    public Transform Player => _player;
    public FollowerStateMachine StateMachine => _followerSM;
    public float FollowDistance => _followDistance;
    public float DetectionRange => _detectionRange;
    public float AttackRange => _attackRange;
    public float FollowSpeed => _followSpeed;

    /// <summary>随从是否处于活跃状态（未被暂停）</summary>
    public bool IsActive => _isActive && !_isPaused;

    /// <summary>暂停/恢复随从 AI（不改变 _isActive，用于陷阱等临时暂停）</summary>
    public void SetPaused(bool paused)
    {
        _isPaused = paused;
        if (paused) _movement?.Stop();
    }

    private void OnEnable()
    {
        ActiveFollowers.Add(this);
        Revision++;

        if (MapManager.Instance != null)
            MapManager.Instance.OnRoomSwitchStarted += OnRoomSwitchStarted;
        SceneManager.sceneLoaded += OnSceneLoaded;
    }

    private void OnDisable()
    {
        ActiveFollowers.Remove(this);
        Revision++;
        if (_core != null && _core.Health != null)
            _core.Health.OnDied -= HandleDeath;
        if (MapManager.Instance != null)
            MapManager.Instance.OnRoomSwitchStarted -= OnRoomSwitchStarted;
        SceneManager.sceneLoaded -= OnSceneLoaded;
    }

    private void Awake()
    {
        _core = GetComponent<EnemyCore>();
    }

    /// <summary>
    /// 激活随从模式。
    /// </summary>
    /// <param name="player">玩家 Transform</param>
    /// <param name="slotIndex">槽位索引（-1=自动分配最小空闲槽）</param>
    public void Activate(Transform player, int slotIndex = -1)
    {
        _player = player;
        _isActive = true;

        // 槽位分配：显式指定或自动取最小空闲槽
        SlotIndex = slotIndex >= 0 ? slotIndex : FindFreeSlotIndex();

        _movement = _core.Movement;
        _skillManager = _core.SkillManager;

        // 记录原始属性，用于进化倾向 buff 重算
        if (_core.Health != null)
        {
            _origMaxHealth = _core.Health.MaxHealth;
            _origPatrolSpeed = _core.Health.PatrolSpeed;
            _origChaseSpeed = _core.Health.ChaseSpeed;
            _origDetectionRange = _core.Health.DetectionRange;
            _origAttackRange = _core.Health.AttackRange;
            _origContactDamage = _core.Health.ContactDamage;
            _origContactDamageCooldown = _core.Health.ContactDamageCooldown;

            // 应用当前进化倾向 buff
            ApplyEvolutionBuff();

            _core.Health.OnDied += HandleDeath;
        }

        // 先脱离房间父节点，再标记 DontDestroyOnLoad（对有父节点的子对象直接调用不生效）
        transform.SetParent(null);
        DontDestroyOnLoad(gameObject);

        // 创建随从状态机并启动
        _followerSM = new FollowerStateMachine();
        _followerSM.ChangeState(new FollowerIdleState(this));
    }

    /// <summary>根据玩家进化倾向刷新随从全属性增幅（叠加道具乘区）</summary>
    public void ApplyEvolutionBuff()
    {
        if (_core?.Health == null || !_isActive) return;

        var playerStats = _player?.GetComponent<PlayerStats>();
        if (playerStats == null) return;

        float tendency = playerStats.EvolutionTendency;
        float factor = playerStats.EvolveFollowerBuffFactor;
        float levelMult = 1f + (Level - 1) * _levelStatFactor;
        float mult = Mathf.Max(0f, 1f + (-tendency) * factor) * levelMult;

        _core.Health.MaxHealth = Mathf.Max(_origMaxHealth * mult * MaxHealthMultiplier, 1f);
        _core.Health.PatrolSpeed = _origPatrolSpeed * mult;
        _core.Health.ChaseSpeed = _origChaseSpeed * mult;
        _core.Health.DetectionRange = _origDetectionRange * mult;
        _core.Health.AttackRange = _origAttackRange * mult;
        _core.Health.ContactDamage = _origContactDamage * mult * DamageMultiplier;
        _core.Health.ContactDamageCooldown = _origContactDamageCooldown * mult;

        // 应用随从技能冷却乘区
        if (_skillManager != null)
        {
            foreach (var s in _skillManager.SkillInstances)
                s.CooldownFactor = FollowerCooldownFactor;
        }
    }

    /// <summary>刷新所有活跃随从的进化倾向 buff（由 PlayerStats 在倾向值变化时调用）</summary>
    public static void RefreshAllFollowers(float tendency, float factor)
    {
        foreach (var f in ActiveFollowers)
            f.ApplyEvolutionBuff();
    }

    /// <summary>刷新所有活跃随从（道具增强变化时调用）</summary>
    public static void RefreshAllFollowers()
    {
        foreach (var f in ActiveFollowers)
            f.ApplyEvolutionBuff();
    }

    private void Update()
    {
        if (!_isActive || _isPaused || _player == null) return;
        if (_core.Health != null && _core.Health.IsDead) return;

        // 离玩家过远 → 直接传送到身边，防止掉队或被卡住
        float sqrDistToPlayer = ((Vector2)transform.position - (Vector2)_player.position).sqrMagnitude;
        if (sqrDistToPlayer > _maxTeleportDistance * _maxTeleportDistance)
        {
            _movement?.Teleport(_player.position);
            return;
        }

        _followerSM?.Tick();
    }

    /// <summary>在检测范围内查找最近的 "Enemy" 标签目标</summary>
    public Transform FindNearestEnemy(Vector2 center)
    {
        Collider2D[] hits = Physics2D.OverlapCircleAll(center, _detectionRange);
        Transform nearest = null;
        float minDist = float.MaxValue;

        foreach (var hit in hits)
        {
            if (!hit.CompareTag("Enemy")) continue;
            if (_player != null && hit.transform == _player) continue;

            float d = (hit.transform.position - (Vector3)center).sqrMagnitude;
            if (d < minDist)
            {
                minDist = d;
                nearest = hit.transform;
            }
        }

        return nearest;
    }

    private void OnRoomSwitchStarted(int fromRoomId, int toRoomId)
    {
        // 随从传送由 MapManager.TeleportFollowers 统一处理（在玩家传送到新房间之后）
    }

    private void HandleDeath()
    {
        _isActive = false;
        _isReviving = true;

        // 停止状态机
        _followerSM?.ChangeState(null);

        // 禁用碰撞
        foreach (var col in GetComponentsInChildren<Collider2D>())
            col.enabled = false;

        _movement?.Stop();

        // 隐藏视觉
        foreach (var sr in GetComponentsInChildren<SpriteRenderer>())
            sr.enabled = false;

        StartCoroutine(RespawnRoutine());
    }

    private IEnumerator RespawnRoutine()
    {
        yield return new WaitForSeconds(_respawnDelay);

        // 复活
        if (_core?.Health != null)
        {
            _core.Health.Revive();
            ApplyEvolutionBuff();
        }

        // 传送到玩家身边
        if (_player != null)
            _movement?.Teleport(_player.position);

        // 恢复视觉和碰撞
        foreach (var sr in GetComponentsInChildren<SpriteRenderer>())
            sr.enabled = true;
        foreach (var col in GetComponentsInChildren<Collider2D>())
            col.enabled = true;

        _isActive = true;
        _isReviving = false;

        // 重启状态机
        _followerSM?.ChangeState(new FollowerIdleState(this));
    }

    private void OnSceneLoaded(Scene scene, LoadSceneMode mode)
    {
        if (scene.name == "Start" || scene.name == "Result" || scene.name == "Winning")
        {
            Destroy(gameObject);
            return;
        }

        // 游戏场景：重新查找玩家引用
        if (PlayerManager.Instance != null && PlayerManager.Instance.CurrentPlayer != null)
            _player = PlayerManager.Instance.CurrentPlayer.transform;
        else
            _player = GameObject.FindGameObjectWithTag("Player")?.transform;

        // 传送到玩家身边（防止随从出现在旧位置）
        if (_player != null && _movement != null && !_isReviving)
            _movement.Teleport(_player.position);
    }

    // ── 槽位与升级 ──

    /// <summary>查找最小空闲槽位索引（0..MaxFollowerCount-1），满员返回 MaxFollowerCount</summary>
    private int FindFreeSlotIndex()
    {
        var used = new System.Collections.Generic.HashSet<int>();
        foreach (var f in ActiveFollowers)
        {
            if (f != this && f.SlotIndex >= 0)
                used.Add(f.SlotIndex);
        }

        for (int i = 0; i < MaxFollowerCount; i++)
        {
            if (!used.Contains(i))
                return i;
        }
        return MaxFollowerCount;
    }

    /// <summary>按槽位顺序返回随从列表（空槽为 null，长度 = MaxFollowerCount）</summary>
    public static System.Collections.Generic.List<EnemyFollower> GetSlotsInOrder()
    {
        var list = new System.Collections.Generic.List<EnemyFollower>();
        for (int i = 0; i < MaxFollowerCount; i++)
        {
            EnemyFollower found = null;
            foreach (var f in ActiveFollowers)
            {
                if (f.SlotIndex == i)
                {
                    found = f;
                    break;
                }
            }
            list.Add(found);
        }
        return list;
    }

    /// <summary>判断两个敌人是否同种类（config 引用相等，config 为空回退 displayName）</summary>
    public static bool SameType(EnemyCore a, EnemyCore b)
    {
        if (a == null || b == null) return false;

        var ca = a.config;
        var cb = b.config;
        if (ca != null && cb != null) return ca == cb;

        return string.Equals(ca != null ? ca.displayName : null,
                             cb != null ? cb.displayName : null);
    }

    /// <summary>
    /// 升级随从：等级 +1，属性按 _levelStatFactor 提升，技能等级 +1（可选）。
    /// </summary>
    public void UpgradeLevel()
    {
        Level++;

        if (_upgradeSkillsOnLevelUp && _skillManager != null)
        {
            foreach (var s in _skillManager.SkillInstances)
                s?.TryUpgrade();
        }

        ApplyEvolutionBuff();
        Revision++;
    }

    /// <summary>
    /// 把敌人同化到指定槽位：空槽=放置；同种=升级并消耗敌人；异种=替换（销毁旧随从）。
    /// 成功路径都会触发 OnAssimilated（供房间计数/门锁逻辑）。
    /// </summary>
    public static FollowerSlotResult AssimilateToSlot(EnemyCore enemy, Transform player, int slotIndex)
    {
        if (enemy == null || player == null)
            return FollowerSlotResult.Failed;

        var slots = GetSlotsInOrder();
        if (slotIndex < 0 || slotIndex >= slots.Count)
            return FollowerSlotResult.Failed;

        var existing = slots[slotIndex];

        // 同种升级：提升现有随从等级，消耗被侵蚀的敌人（不创建新随从）
        if (existing != null && SameType(existing.Core, enemy))
        {
            existing.UpgradeLevel();
            enemy.ConsumeAsAssimilated(player);
            return FollowerSlotResult.Upgraded;
        }

        // 替换：同步销毁旧随从释放槽位（时间缩放 0 时 Destroy 延后一帧会导致槽位短暂重复）
        // 注意：DestroyImmediate 后 Unity 对象判空（existing != null）会变为 false，须先缓存布尔值
        bool hadExisting = existing != null;
        if (hadExisting)
            DestroyImmediate(existing.gameObject);

        // 放置/替换：同化敌人到指定槽位
        enemy.Assimilate(player, slotIndex);
        return hadExisting ? FollowerSlotResult.Replaced : FollowerSlotResult.Placed;
    }
}

/// <summary>同化到槽位的操作结果</summary>
public enum FollowerSlotResult
{
    Failed,
    Placed,
    Upgraded,
    Replaced
}

using UnityEngine;

/// <summary>
/// 追击状态：高速追向玩家。
/// 脱战距离 = 3× detectionRange，短暂失去视线切 SearchState。
/// 进入攻击范围 → AttackState。
/// </summary>
public class ChaseState : EnemyStateBase
{
    public ChaseState(EnemyCore core) : base(core) { }

    public override void Tick()
    {
        if (Core.PlayerTarget == null || Core.Health == null)
        {
            Core.StateMachine.ChangeState(new IdleState(Core));
            return;
        }

        Vector2 playerPos = Core.PlayerTarget.position;
        float sqrDist = ((Vector2)Core.transform.position - playerPos).sqrMagnitude;
        float attackSqr = Core.Health.AttackRange * Core.Health.AttackRange;

        // 脱战判定：3× detectionRange
        float leashRange = Core.Health.DetectionRange * 3f;
        if (sqrDist > leashRange * leashRange)
        {
            Core.Movement?.Stop();
            Core.StateMachine.ChangeState(new IdleState(Core));
            return;
        }

        // 视线检测
        bool canSee = Core.Movement.HasLineOfSight(playerPos, Core.Health.DetectionRange);
        if (!canSee)
        {
            Core.StateMachine.ChangeState(new SearchState(Core));
            return;
        }

        Core.LastKnownPlayerPosition = playerPos;

        // 轴向喷射型敌人（结核分枝杆菌）：进入攻击范围即进入喷射状态（沿三个固定角发射），而非继续追击
        if (Core.config != null && Core.config.useAxialSpray)
        {
            if (sqrDist <= attackSqr)
            {
                Core.StateMachine.ChangeState(new AxialSprayState(Core));
                return;
            }
        }

        // Boss 张嘴冲刺型（巨噬细胞 Boss）：同行/同列时进入冲刺状态
        if (Core.config != null && Core.config.useBossLunge && Core.GetComponent<BossCore>() != null)
        {
            float threshold = Core.config.axialAlignThreshold > 0f ? Core.config.axialAlignThreshold : 0.6f;
            bool aligned = Mathf.Abs(playerPos.x - Core.transform.position.x) <= threshold
                        || Mathf.Abs(playerPos.y - Core.transform.position.y) <= threshold;
            if (aligned)
            {
                Core.StateMachine.ChangeState(new BossLungeState(Core));
                return;
            }
        }

        // 进入攻击范围
        if (sqrDist <= attackSqr)
        {
            Core.StateMachine.ChangeState(new AttackState(Core));
            return;
        }

        // 追击（A* 寻路）
        var path = Core.Movement.GetPath(playerPos);
        Core.Movement?.MoveAlongPath(path, Core.Health.ChaseSpeed);
    }
}

using UnityEngine;

/// <summary>
/// 搜索状态：移动到玩家最后已知位置，到达后等待 searchDuration 秒。
/// 重新发现玩家 → ChaseState；超时 → IdleState。
/// </summary>
public class SearchState : EnemyStateBase
{
    private float _enterTime;
    private float _searchDuration = 2.5f;
    private bool _arrived;
    private static readonly float ArriveThreshold = 0.4f;

    public SearchState(EnemyCore core) : base(core) { }

    public override void Enter()
    {
        _enterTime = Time.time;
        _arrived   = false;
    }

    public override void Tick()
    {
        // 期间重新发现玩家 → 立即追击
        if (Core.PlayerTarget != null && Core.Health != null)
        {
            Vector2 playerPos = Core.PlayerTarget.position;
            if (Core.Movement.HasLineOfSight(playerPos, Core.Health.DetectionRange))
            {
                Core.LastKnownPlayerPosition = playerPos;
                Core.StateMachine.ChangeState(new ChaseState(Core));
                return;
            }
        }

        Vector2 lastPos = Core.LastKnownPlayerPosition;
        float sqrDist = ((Vector2)Core.transform.position - lastPos).sqrMagnitude;

        if (!_arrived)
        {
            if (sqrDist < ArriveThreshold * ArriveThreshold)
            {
                _arrived   = true;
                _enterTime = Time.time;
                Core.Movement?.Stop();
            }
            else
            {
                // 搜索时用 patrolSpeed，额外减速 0.8（A* 寻路）
                var path = Core.Movement.GetPath(lastPos);
                Core.Movement?.MoveAlongPath(path,
                    Core.Health != null ? Core.Health.PatrolSpeed : 1f, 0.8f);
            }
        }
        else
        {
            Core.Movement?.Stop();
            if (Time.time - _enterTime > _searchDuration)
            {
                Core.StateMachine.ChangeState(new IdleState(Core));
            }
        }
    }
}

using System.Collections.Generic;
using UnityEngine;

/// <summary>
/// 地图生成器 — 基于配置生成房间图谱和布局
/// 
/// 算法:
/// 1. 从 Start 房间开始 (放置在中心)
/// 2. BFS 扩展: 每次从已放置房间的未占用门出口
/// 3. 随机选取匹配门方向的房间配置
/// 4. 根据门的本地坐标对齐相邻房间
/// 5. Boss 放最后，隐藏房从非终点的开放门放置
/// </summary>
public class MapGenerator
{
    private MapConfig _config;
    private int _seed;

    public MapGenerator(MapConfig config)
    {
        _config = config;
    }

    /// <summary>生成房间图</summary>
    public RoomGraph Generate(int seed)
    {
        _seed = seed;
        if (_seed != 0)
            Random.InitState(_seed);
        else
            Random.InitState(System.DateTime.Now.Millisecond);

        var graph = new RoomGraph();

        if (_config.startRoom == null)
        {
            Debug.LogError("MapGenerator: startRoom 未配置");
            return graph;
        }

        // 1. 放置 Start 房间在中心
        var startNode = graph.AddNode(_config.startRoom, RoomType.Start, Vector2.zero);
        graph.startRoomId = startNode.roomId;

        // 2. 构建需要生成的房间类型队列 (打乱顺序)
        var roomTypeQueue = BuildRoomTypeQueue();

        // 3. BFS 放置
        var placedOpenDoors = new List<(int roomId, DoorDirection dir)>();
        AddOpenDoors(placedOpenDoors, startNode);

        var placedRoomIds = new List<int> { startNode.roomId };
        int typeQueueIndex = 0;
        int failsafe = 0;
        const int maxAttempts = 200;

        while (typeQueueIndex < roomTypeQueue.Count && placedOpenDoors.Count > 0 && failsafe < maxAttempts)
        {
            failsafe++;

            // 随机选一个开放的门
            int doorIdx = Random.Range(0, placedOpenDoors.Count);
            var (anchorId, anchorDir) = placedOpenDoors[doorIdx];
            placedOpenDoors.RemoveAt(doorIdx);

            var anchorNode = graph.GetNode(anchorId);
            if (anchorNode == null) continue;

            RoomType targetType = roomTypeQueue[typeQueueIndex];

            // Boss 不与 Start 房间直连，跳过该门
            if (targetType == RoomType.Boss && anchorNode.roomType == RoomType.Start)
                continue;

            RoomConfig[] pool = _config.GetPoolForType(targetType);

            if (pool == null || pool.Length == 0)
            {
                // 跳过没有配置该类型池的类型
                typeQueueIndex++;
                // 把这个门放回去，留给下一个房间
                placedOpenDoors.Add((anchorId, anchorDir));
                continue;
            }

            // 随机选取匹配门方向的房间
            var targetDir = RoomConfig.OppositeDir(anchorDir);
            var candidates = new List<RoomConfig>();
            foreach (var rc in pool)
            {
                if (rc != null && rc.HasDoor(targetDir))
                    candidates.Add(rc);
            }

            if (candidates.Count == 0)
            {
                // 没有可用的候选，跳过
                continue;
            }

            var chosenConfig = candidates[Random.Range(0, candidates.Count)];

            // 计算新房间位置
            Vector2 anchorDoorWorld = anchorNode.GetDoorWorldPosition(anchorDir);
            Vector2 targetDoorLocal = chosenConfig.GetDoorOffset(targetDir);
            Vector2 newPos = anchorDoorWorld - targetDoorLocal;

            // 碰撞检测
            var newBounds = new Rect(newPos - chosenConfig.roomSize * 0.5f, chosenConfig.roomSize);
            if (OverlapsAny(graph, newBounds))
            {
                // 放回门，稍后重试
                placedOpenDoors.Add((anchorId, anchorDir));
                continue;
            }

            // 成功放置
            var newNode = graph.AddNode(chosenConfig, targetType, newPos);
            graph.Connect(anchorId, newNode.roomId, anchorDir, targetDir);
            placedRoomIds.Add(newNode.roomId);

            // 将新房间的未连接门加入开放列表
            AddOpenDoors(placedOpenDoors, newNode, targetDir);

            typeQueueIndex++;
        }

        // 放置隐藏房：从非 Boss 房间的开放门中随机选取放置
        PlaceHiddenRooms(graph, placedOpenDoors);

        if (failsafe >= maxAttempts)
            Debug.LogWarning("MapGenerator: 达到最大尝试次数，可能未生成全部房间");

        Debug.Log($"MapGenerator: 生成了 {graph.nodes.Count} 个房间 (预期 {_config.TotalRooms})");
        return graph;
    }

    /// <summary>构建房间类型队列 (打乱，最终 Boss 放最后)</summary>
    private List<RoomType> BuildRoomTypeQueue()
    {
        var queue = new List<RoomType>();

        for (int i = 0; i < _config.normalRoomCount; i++)
            queue.Add(RoomType.Normal);
        for (int i = 0; i < _config.treasureRoomCount; i++)
            queue.Add(RoomType.Treasure);
        for (int i = 0; i < _config.shopRoomCount; i++)
            queue.Add(RoomType.Shop);

        // 最终房间：Boss 放最后
        for (int i = 0; i < _config.bossRoomCount; i++)
            queue.Add(RoomType.Boss);

        // 打乱除最后一个 (Boss) 以外的所有房间
        int shuffleCount = queue.Count - 1;
        for (int i = 0; i < shuffleCount; i++)
        {
            int j = Random.Range(i, shuffleCount);
            (queue[i], queue[j]) = (queue[j], queue[i]);
        }

        return queue;
    }

    /// <summary>将房间的未使用门加入开放列表</summary>
    private void AddOpenDoors(List<(int roomId, DoorDirection dir)> openDoors, RoomNode node, 
        DoorDirection? excludeDir = null)
    {
        var allDirs = new[] { DoorDirection.Top, DoorDirection.Bottom, DoorDirection.Left, DoorDirection.Right };
        foreach (var dir in allDirs)
        {
            if (excludeDir.HasValue && dir == excludeDir.Value) continue;
            if (node.config.HasDoor(dir))
                openDoors.Add((node.roomId, dir));
        }
    }

    /// <summary>放置隐藏房：从非 Boss 房间的开放门中随机选取放置</summary>
    private void PlaceHiddenRooms(RoomGraph graph, 
        List<(int roomId, DoorDirection dir)> openDoors)
    {
        if (_config.hiddenRoomPool == null || _config.hiddenRoomPool.Length == 0) return;
        int count = _config.hiddenRoomCount;
        if (count <= 0) return;

        // 收集非 Boss 房间的开放门
        var eligibleDoors = new List<(int roomId, DoorDirection dir)>();
        foreach (var od in openDoors)
        {
            var node = graph.GetNode(od.roomId);
            if (node == null) continue;
            if (node.roomType == RoomType.Boss) continue;
            eligibleDoors.Add(od);
        }

        if (eligibleDoors.Count == 0) return;

        int placed = 0;
        int failsafe = 0;
        const int maxAttempts = 50;

        while (placed < count && eligibleDoors.Count > 0 && failsafe < maxAttempts)
        {
            failsafe++;

            // 随机选一个可用的开放门
            int idx = Random.Range(0, eligibleDoors.Count);
            var (anchorId, anchorDir) = eligibleDoors[idx];
            eligibleDoors.RemoveAt(idx);

            var anchorNode = graph.GetNode(anchorId);
            if (anchorNode == null) continue;

            var targetDir = RoomConfig.OppositeDir(anchorDir);

            // 选取匹配的隐藏房配置
            var candidates = new List<RoomConfig>();
            foreach (var rc in _config.hiddenRoomPool)
            {
                if (rc != null && rc.HasDoor(targetDir))
                    candidates.Add(rc);
            }
            if (candidates.Count == 0) continue;

            var chosenConfig = candidates[Random.Range(0, candidates.Count)];

            Vector2 anchorDoorWorld = anchorNode.GetDoorWorldPosition(anchorDir);
            Vector2 targetDoorLocal = chosenConfig.GetDoorOffset(targetDir);
            Vector2 newPos = anchorDoorWorld - targetDoorLocal;

            var newBounds = new Rect(newPos - chosenConfig.roomSize * 0.5f, chosenConfig.roomSize);
            if (OverlapsAny(graph, newBounds)) continue;

            var newNode = graph.AddNode(chosenConfig, RoomType.Hidden, newPos);
            graph.Connect(anchorId, newNode.roomId, anchorDir, targetDir);
            // 不把隐藏房的门加入开放列表 (保证只有一个连接)
            placed++;
        }

        if (placed < count)
            Debug.LogWarning($"MapGenerator: 只放置了 {placed}/{count} 个隐藏房");
    }

    /// <summary>检查矩形是否与已有房间重叠。
    /// 相邻房间共享边界 (edge-to-edge) 不算重叠，只有真正交叉才算冲突。
    /// roomSpacing 用作最小间距。
    /// </summary>
    private bool OverlapsAny(RoomGraph graph, Rect bounds)
    {
        // 缩一圈来确保最小间距 (只对真正相交的生效)
        float shrink = _config.roomSpacing * 0.5f;
        var checkRect = new Rect(
            bounds.x + shrink,
            bounds.y + shrink,
            bounds.width - shrink * 2,
            bounds.height - shrink * 2
        );

        foreach (var node in graph.nodes)
        {
            var otherRect = new Rect(
                node.Bounds.x + shrink,
                node.Bounds.y + shrink,
                node.Bounds.width - shrink * 2,
                node.Bounds.height - shrink * 2
            );

            if (checkRect.Overlaps(otherRect))
                return true;
        }
        return false;
    }
}

using System.Collections.Generic;
using UnityEngine;

/// <summary>
/// 房间图 — 描述所有房间及其连接关系
/// </summary>
[System.Serializable]
public class RoomGraph
{
    /// <summary>所有房间节点</summary>
    public List<RoomNode> nodes = new();

    /// <summary>起始房间 ID</summary>
    public int startRoomId;

    private int _nextId;

    /// <summary>添加房间节点</summary>
    public RoomNode AddNode(RoomConfig config, RoomType type, Vector2 worldPos)
    {
        var node = new RoomNode
        {
            roomId = _nextId++,
            config = config,
            roomType = type,
            worldPosition = worldPos
        };
        nodes.Add(node);
        return node;
    }

    /// <summary>连接两个房间的门</summary>
    public void Connect(int fromId, int toId, DoorDirection fromDir, DoorDirection toDir)
    {
        var from = GetNode(fromId);
        var to = GetNode(toId);
        if (from == null || to == null) return;

        from.connections[toId] = fromDir;
        to.connections[fromId] = toDir;
    }

    /// <summary>根据 ID 获取节点</summary>
    public RoomNode GetNode(int id)
    {
        return nodes.Find(n => n.roomId == id);
    }

    /// <summary>获取相邻房间列表</summary>
    public List<RoomNode> GetAdjacent(int id)
    {
        var node = GetNode(id);
        if (node == null) return new List<RoomNode>();

        var result = new List<RoomNode>();
        foreach (var conn in node.connections)
        {
            var adj = GetNode(conn.Key);
            if (adj != null) result.Add(adj);
        }
        return result;
    }
}

using System.Collections.Generic;
using UnityEngine;

/// <summary>
