using System.Collections.Generic;
using UnityEngine;

/// <summary>
/// A* 寻路算法 — Octile Distance 启发式，8 方向移动，拐角检查。
/// </summary>
public static class AStarPathfinder
{
    private const float D = 1f;        // 直线移动代价
    private const float D2 = 1.4142f;  // 对角线移动代价 (√2)

    /// <summary>
    /// 返回从 start 到 end 的路径点列表（世界坐标），不含起点，含终点。
    /// 无路径返回 null。
    /// </summary>
    public static List<Vector2> FindPath(Vector2 start, Vector2 end,
        PathfindingGrid grid, int maxNodes = 500)
    {
        var startCell = grid.WorldToCell(start);
        var endCell = grid.WorldToCell(end);

        if (!grid.InBounds(startCell.x, startCell.y))
            startCell = grid.ClampToGrid(start);
        if (!grid.InBounds(endCell.x, endCell.y))
            endCell = grid.ClampToGrid(end);

        if (!grid.IsWalkable(endCell.x, endCell.y))
        {
            endCell = grid.FindNearestWalkable(endCell);
            if (endCell.x < 0) return null;
        }

        var openSet = new List<AStarNode>();
        var closedSet = new HashSet<Vector2Int>();
        var cameFrom = new Dictionary<Vector2Int, Vector2Int>();
        var gScore = new Dictionary<Vector2Int, float>();
        var fScore = new Dictionary<Vector2Int, float>();

        var startKey = new Vector2Int(startCell.x, startCell.y);
        var endKey = new Vector2Int(endCell.x, endCell.y);

        gScore[startKey] = 0;
        fScore[startKey] = Heuristic(startCell, endCell);
        openSet.Add(new AStarNode(startKey, fScore[startKey]));

        int nodesExplored = 0;

        while (openSet.Count > 0 && nodesExplored < maxNodes)
        {
            // 取 fScore 最小的节点
            openSet.Sort((a, b) => a.F.CompareTo(b.F));
            var current = openSet[0];
            openSet.RemoveAt(0);

            if (current.Cell == endKey)
                return ReconstructPath(cameFrom, current.Cell, grid);

            closedSet.Add(current.Cell);
            nodesExplored++;

            // 8 方向邻居
            for (int dx = -1; dx <= 1; dx++)
            {
                for (int dy = -1; dy <= 1; dy++)
                {
                    if (dx == 0 && dy == 0) continue;

                    int nx = current.Cell.x + dx;
                    int ny = current.Cell.y + dy;
                    var neighbor = new Vector2Int(nx, ny);

                    if (!grid.InBounds(nx, ny)) continue;
                    if (!grid.IsWalkable(nx, ny)) continue;
                    if (closedSet.Contains(neighbor)) continue;

                    // 对角线拐角检查：两个正交邻居必须均可通行
                    if (dx != 0 && dy != 0)
                    {
                        if (!grid.IsWalkable(current.Cell.x + dx, current.Cell.y)) continue;
                        if (!grid.IsWalkable(current.Cell.x, current.Cell.y + dy)) continue;
                    }

                    float moveCost = (dx != 0 && dy != 0) ? D2 : D;
                    float tentativeG = gScore[current.Cell] + moveCost;

                    if (!gScore.ContainsKey(neighbor) || tentativeG < gScore[neighbor])
                    {
                        cameFrom[neighbor] = current.Cell;
                        gScore[neighbor] = tentativeG;
                        fScore[neighbor] = tentativeG + Heuristic(neighbor, endKey);

                        if (!openSet.Exists(n => n.Cell == neighbor))
                            openSet.Add(new AStarNode(neighbor, fScore[neighbor]));
                    }
                }
            }
        }

        return null; // 无路径
    }

    /// <summary>Octile Distance — 匹配 8 方向移动</summary>
    private static float Heuristic(Vector2Int a, Vector2Int b)
    {
        int dx = Mathf.Abs(a.x - b.x);
        int dy = Mathf.Abs(a.y - b.y);
        return D * (dx + dy) + (D2 - 2f * D) * Mathf.Min(dx, dy);
    }

    /// <summary>重建路径 → 世界坐标列表</summary>
    private static List<Vector2> ReconstructPath(
        Dictionary<Vector2Int, Vector2Int> cameFrom,
        Vector2Int current, PathfindingGrid grid)
    {
        var path = new List<Vector2>();
        var cell = current;
        while (cameFrom.ContainsKey(cell))
        {
            path.Add(grid.CellToWorld(cell.x, cell.y));
            cell = cameFrom[cell];
        }
        path.Reverse();
        return path;
    }

    private struct AStarNode
    {
        public Vector2Int Cell;
        public float F;
        public AStarNode(Vector2Int cell, float f) { Cell = cell; F = f; }
    }
}

using System.Collections.Generic;
using UnityEngine;

/// <summary>
/// 寻路网格 — 运行时构建，存储在 RoomRoot 中供敌人共享。
/// 使用虚拟矩形栅格化检测障碍物（Rect.Overlaps vs Collider.bounds）。
/// </summary>
public class PathfindingGrid
{
    private readonly bool[,] _walkable;
    private readonly Vector2 _origin;
    private readonly float _cellSize;
    private readonly int _width;
    private readonly int _height;

    public int Width => _width;
    public int Height => _height;
    public Vector2 Origin => _origin;
    public float CellSize => _cellSize;

    public PathfindingGrid(Vector2 origin, int width, int height, float cellSize)
    {
        _origin = origin;
        _width = width;
        _height = height;
        _cellSize = cellSize;
        _walkable = new bool[width, height];
    }

    /// <summary>
    /// 虚拟矩形栅格化构建：
    /// 1. 收集房间范围内所有 Wall/Obstacles 的 Collider.bounds
    /// 2. 每个 cell 的 Rect（收缩 shrink）与障碍物 bounds 做交集检测
    /// </summary>
    public static PathfindingGrid Build(Vector2 center, Vector2 roomSize, float cellSize = 1f)
    {
        int width = Mathf.RoundToInt(roomSize.x / cellSize);
        int height = Mathf.RoundToInt(roomSize.y / cellSize);
        Vector2 origin = center - new Vector2(width * cellSize * 0.5f, height * cellSize * 0.5f);

        var grid = new PathfindingGrid(origin, width, height, cellSize);

        // 每个 cell 中心用 OverlapCircle 检测是否有障碍碰撞体
        float checkRadius = cellSize * 0.25f;

        for (int x = 0; x < width; x++)
        {
            for (int y = 0; y < height; y++)
            {
                Vector2 cellCenter = grid.CellToWorld(x, y);
                var hits = Physics2D.OverlapCircleAll(cellCenter, checkRadius);
                bool blocked = false;
                foreach (var hit in hits)
                {
                    if (hit.CompareTag("Wall") || hit.CompareTag("Obstacles") || hit.CompareTag("Spike") || hit.CompareTag("Hole"))
                    {
                        blocked = true;
                        break;
                    }
                }
                grid._walkable[x, y] = !blocked;
            }
        }
        return grid;
    }

    public bool IsWalkable(int x, int y)
    {
        if (!InBounds(x, y)) return false;
        return _walkable[x, y];
    }

    public bool InBounds(int x, int y) => x >= 0 && x < _width && y >= 0 && y < _height;

    public Vector2Int WorldToCell(Vector2 worldPos)
    {
        Vector2 local = worldPos - _origin;
        return new Vector2Int(
            Mathf.FloorToInt(local.x / _cellSize),
            Mathf.FloorToInt(local.y / _cellSize));
    }

    public Vector2 CellToWorld(int x, int y)
    {
        return _origin + new Vector2(
            (x + 0.5f) * _cellSize,
            (y + 0.5f) * _cellSize);
    }

    public Vector2Int ClampToGrid(Vector2 worldPos)
    {
        var cell = WorldToCell(worldPos);
        cell.x = Mathf.Clamp(cell.x, 0, _width - 1);
        cell.y = Mathf.Clamp(cell.y, 0, _height - 1);
        return cell;
    }

    /// <summary>找最近的可通行 cell（螺旋搜索）</summary>
    public Vector2Int FindNearestWalkable(Vector2Int center)
    {
        if (IsWalkable(center.x, center.y)) return center;
        for (int r = 1; r < 10; r++)
        {
            for (int dx = -r; dx <= r; dx++)
            {
                for (int dy = -r; dy <= r; dy++)
                {
                    if (Mathf.Max(Mathf.Abs(dx), Mathf.Abs(dy)) != r) continue;
                    int x = center.x + dx;
                    int y = center.y + dy;
                    if (InBounds(x, y) && IsWalkable(x, y))
                        return new Vector2Int(x, y);
                }
            }
        }
        return new Vector2Int(-1, -1);
    }
}

